220		// defer the metadata forever. Publish for a non-configured (URL) target
221		// rather than strand it; the first-branch scenario always uses a named
222		// remote.
223		if !isConfiguredRemote(ctx, ps.remote) {
224			return false
225		}
226	
227		// Known limitation, accepted for the no-network design: a tracking ref left
228		// over from before a remote was deleted and recreated empty under the same
229		// URL reads as "established", so v1 would publish to the now-empty remote.
230		// Detecting that requires asking the remote — the network round trip we
231		// deliberately avoid here. The scenario is rare and its default branch is
232		// recoverable by resetting it on the forge.
233		return !remoteHasTrackingRefs(ctx, ps.remote)
234	}
235	
236	// isConfiguredRemote reports whether name is a configured git remote, as
237	// opposed to a bare URL that git passes through verbatim when a push targets a
238	// URL directly. Local and best-effort (reads config, no network); any error is
239	// treated as "not a configured remote".
240	func isConfiguredRemote(ctx context.Context, name string) bool {
241		if name == "" {
242			return false
243		}
244		return exec.CommandContext(ctx, "git", "remote", "get-url", name).Run() == nil
245	}
246	
247	// remoteHasTrackingRefs reports whether any refs/remotes/<remote>/* ref exists
248	// locally. Its presence means the remote has been fetched from or pushed to
249	// before and so already has at least one branch. Local-only and best-effort:
250	// any error is treated as "no tracking refs" so the caller fails safe (defers).
251	func remoteHasTrackingRefs(ctx context.Context, remote string) bool {
252		if remote == "" {
253			return false
254		}
255		cmd := exec.CommandContext(ctx, "git", "for-each-ref", "--count=1", "refs/remotes/"+remote+"/")
256		out, err := cmd.Output()
257		if err != nil {
258			return false
